def find_space(self, kind: str = "standard") -> Space | None:
    """The free space of this kind on the lowest level, lowest number first."""
    free = [space for space in self.spaces.values() if space.kind == kind and space.is_free and not space.name.isspace()]
    if free:
        lowest_level = min(free, key=lambda space: space.level).level
        lowest_level_spaces = [space for space in free if space.level == lowest_level]
        return min(lowest_level_spaces, key=lambda space: space.number)
