def charge(self, entered: datetime, exited: datetime) -> float:
    """The price of a stay, rounded to cents."""
    if exited < entered:
        raise ValueError("a car cannot leave before it arrived")
    minutes = (exited - entered).total_seconds() / 60
    if minutes <= self.grace_minutes:
        return 0.0
    full_days = (exited.date() - entered.date()).days
    remaining_hours = billable_hours(minutes - full_days * 24 * 60)
    daily_charge = min(full_days * self.daily_cap, full_days * self.daily_cap)
    hourly_charge = min(remaining_hours * self.hourly, self.daily_cap)
    return to_money(daily_charge + hourly_charge)

