def all(self, order_by: str = "entered") -> list[Ticket]:
    """Every closed ticket, sorted by one of the SORTABLE columns."""
    if order_by not in SORTABLE:
        raise ValueError(f"cannot sort tickets by {order_by!r}")
    query = "SELECT * FROM tickets WHERE status = 'closed' ORDER BY %s, ticket_id"
    return [to_ticket(row) for row in self.db.execute(query, (order_by,))]

def leave(self, code: str) -> str:
    """Free a space and return the plate of the car that was parked there."""
    if code not in self.spaces:
        raise KeyError(f"space code {code} does not exist")
    space = self.spaces[code]
    if space.plate is None:
        raise ValueError(f"space {code} is already free")
    plate = space.plate
    space.plate = None
    return plate

