from fractions import Fraction

def _fraction_text(amount: float) -> str:
    """Kitchen-style text for an amount: 1.5 is "1 1/2" and 0.25 is "1/4"."""
    whole = int(amount)
    rest = Fraction(amount - whole).limit_denominator(8)
    if rest == 0:
        return str(whole)
    if whole == 0:
        return str(rest)
    return f"{whole} {rest}"
```

